css:
.tt-container {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-image: linear-gradient(0, #4a494e, #828186);
}

.launch-btn {
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;

  .input {
    opacity: 0;
    width: 0;
    height: 0;
    display: none;

    &:checked ~ .back {
      .spot-shadow {
        transition: 1.7s opacity;
        opacity: 0.9;
        animation: spot-main 1.9s linear infinite;
      }

      .mid {
        .spot-main {
          transition: 1.7s opacity;
          opacity: 0.9;
          animation: spot-main 1.9s linear infinite;
        }

        .btn {
          .spot-light {
            transition: 1.7s opacity;
            opacity: 0.9;
            animation: spot-main 1.9s linear infinite;
          }

          .center {
            .icon .svg {
              filter: brightness(1.15);
            }

            .launch {
              color: #333333;

              > div {
                animation: waveText 1.8s calc(var(--i) * -0.13s) infinite;
              }
            }

            .start {
              .text1 {
                transition: 0.5s;
                transform: translateX(10px);
                opacity: 0;
              }

              .text2 {
                opacity: 1;
                animation: text2 0.5s forwards;
              }
            }
          }
        }
      }
    }
  }

  &:active {
    .back {
      .mid {
        .btn {
          transform: scale(0.94);
          box-shadow:
            0 -1px 2px rgba(255, 255, 255, 0.3),
            inset 0 0 10px rgba(0, 0, 0, 0.24),
            inset 0 -13px 26px rgba(0, 0, 0, 0.8);
        }
      }
    }
  }
}

.back {
  z-index: 200;
  width: 188px;
  height: 188px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
  background-image: linear-gradient(0, #5e5e61 20%, #212123);
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.3),
    inset 0 3px 5px rgba(255, 255, 255, 0.6),
    inset 0 -6px 2px rgba(255, 255, 255, 0.05),
    inset 0 -3px 0 rgba(0, 0, 0, 0.15),
    inset -2px 5px 0 rgba(0, 0, 0, 0.3),
    inset 2px 5px 0 rgba(0, 0, 0, 0.3),
    0 -11px 22px 2px rgba(255, 255, 255, 0.39),
    0 6px 22px 2px rgba(0, 0, 0, 0.5),
    0 2px 6px #7c7c7c;
  cursor: pointer;

  .spot-shadow {
    position: absolute;
    width: 140px;
    height: 40px;
    background: rgba(71, 164, 239, 0.8);
    opacity: 0;
    filter: blur(20px) brightness(1.1);
  }

  .mid {
    overflow: hidden;
    position: relative;
    width: 155px;
    height: 155px;
    display: flex;
    justify-content: center;
    align-items: center;
    border-radius: 50%;
    background: #000;
    box-shadow:
      0 0 5px #000,
      0 1px 2px rgba(255, 255, 255, 0.8);

    &::before {
      content: "";
      position: absolute;
      z-index: 500;
      width: 100%;
      height: 100%;
      border-radius: 50%;
      background: transparent;
      box-shadow: inset 0 -18px 27px rgba(0, 0, 0, 0.8);
      pointer-events: none;
    }

    .spot-main {
      position: absolute;
      width: 160px;
      height: 36px;
      background: #589cf6;
      opacity: 0;
      filter: blur(15px) brightness(1.5);
    }

    .btn {
      z-index: 90;
      display: flex;
      justify-content: center;
      align-items: center;
      width: 146px;
      height: 146px;
      border-radius: 50%;
      background: #424242;
      box-shadow:
        0 -1px 2px rgba(255, 255, 255, 0.5),
        inset 0 -13px 26px rgba(0, 0, 0, 0.8);
      transition: 0.2s ease;

      .spot-light {
        position: absolute;
        width: 160px;
        height: 40px;
        opacity: 0;
        background: rgba(104, 151, 255, 0.4);
        filter: blur(20px) brightness(1.1);
      }

      .center {
        z-index: 100;
        width: 125px;
        height: 125px;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 3px;
        border-radius: 50%;
        background: #232323;
        cursor: pointer;

        .icon svg {
          margin-top: -4px;
          width: 26px;
          filter: brightness(1) grayscale(1);
          transition: 1.5s filter;
        }

        .launch {
          display: flex;
          margin-top: -4px;
          font-size: 19px;
          color: #595959;
        }

        .start {
          font-size: 12px;
          color: #737373;
          text-align: center;
          transition: 0.2s;

          > div {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
          }

          .text1 {
            transition: 0.2s;
          }

          .text2 {
            opacity: 0;
            top: 65%;

            > span {
              animation: waveText 1.8s calc(var(--n) * -0.13s) infinite;
            }
          }
        }
      }
    }
  }
}

@keyframes waveText {
  0% {
    opacity: 0.7;
  }

  50% {
    color: #c6c6c6;
    opacity: 1;
  }

  100% {
    opacity: 0.7;
  }
}

@keyframes spot-main {
  0% {
    transform: rotate(0);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes text2 {
  0% {
    transform: translateX(-80%);
  }

  100% {
    transform: translateX(-50%);
  }
}
